static int lir_type_kind(const char * s) {
    size_t n;
    if ((((!s) || (!s[0])) || (strcmp(s, "void") == 0))) {
        return LTY_VOID;
    }
    if (strstr(s, "(*)")) {
        return LTY_FN;
    }
    if (strncmp(s, "struct ", 7) == 0) {
        return LTY_STRUCT;
    }
    if (strncmp(s, "union ", 6) == 0) {
        return LTY_UNION;
    }
    if (strncmp(s, "enum ", 5) == 0) {
        return LTY_ENUM;
    }
    if (strchr(s, '<')) {
        return LTY_INST;
    }
    n = strlen(s);
    if (((n > 0) && (s[(n - 1)] == '*'))) {
        return LTY_PTR;
    }
    return LTY_PRIM;
}
