static const char * lir_tmp_prefix(int kind) {
    switch (kind) {
        case LTK_RECV:
            return "__ct_recv";
        case LTK_OPT:
            return "__ct_opt";
        case LTK_RET:
            return "__ct_ret";
        case LTK_SRET:
            return "__ct_sret";
        case LTK_NEW:
            return "__ct_new";
        case LTK_Q:
            return "__ct_q";
        case LTK_MATCH:
            return "__ct_match";
        case LTK_SOLD:
            return "__ct_sold";
        default:
            return "__ct_tmp";
    }
}
